import frida
import glob
import json
import os
import queue
import subprocess
import sys
import time


def evaluate(close_fds):
    pending = queue.Queue()
    device = frida.get_local_device()
    sessions = {}
    known = set()

    def emit(kind, **details):
        print(json.dumps({'event': kind, 'close_fds': close_fds, **details}), flush=True)

    def on_child(child):
        pending.put(('child', child))

    device.on('child-added', on_child)
    leaf = "import os,time; print('leaf-ready',os.getpid(),flush=True); time.sleep(0.5)"
    source = ("import os,subprocess,sys; sys.stdin.readline(); "
              "subprocess.Popen([sys.executable,'-u','-c',sys.argv[1]],"
              f"start_new_session=True,close_fds={close_fds!r}); os._exit(7)")
    root = subprocess.Popen([sys.executable, '-u', '-c', source, leaf],
                            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    known.add(root.pid)

    def attach(pid):
        session = device.attach(pid)
        session.on('detached', lambda reason, crash=None: pending.put(('detached', (pid, session, reason))))
        session.enable_child_gating()
        sessions[pid] = session
        emit('gating_enabled', pid=pid)

    try:
        attach(root.pid)
        root.stdin.write(b'go\n')
        root.stdin.flush()
        deadline = time.monotonic() + 6
        while time.monotonic() < deadline:
            try:
                kind, data = pending.get(timeout=1)
            except queue.Empty:
                continue
            if kind == 'child':
                known.add(data.pid)
                emit('child_gated', pid=data.pid, parent_pid=data.parent_pid, origin=str(data.origin))
                attach(data.pid)
                device.resume(data.pid)
            else:
                pid, session, reason = data
                if sessions.get(pid) is session:
                    del sessions[pid]
                emit('detached', pid=pid, reason=reason)
            if root.poll() == 7 and not sessions:
                break
        emit('candidate_result', root_exit=root.poll(), tracked_pids=sorted(known), sessions=list(sessions))
        for pid in known:
            for task in glob.glob(f'/proc/{pid}/task/*'):
                try:
                    with open(task + '/wchan') as source:
                        emit('task_wchan', pid=pid, tid=task.rsplit('/', 1)[1], value=source.read())
                except FileNotFoundError:
                    pass
    finally:
        for pid in sessions:
            try:
                device.kill(pid)
            except frida.ProcessNotFoundError:
                pass
        for session in sessions.values():
            try:
                session.detach()
            except frida.InvalidOperationError:
                pass
        if root.poll() is None:
            root.kill()
        stdout, stderr = root.communicate(timeout=5)
        emit('cleanup', root_exit=root.returncode, stdout=stdout.decode(), stderr=stderr.decode())
        device.off('child-added', on_child)


print(json.dumps({'frida': frida.__version__, 'python': sys.version, 'platform': sys.platform}), flush=True)
evaluate(False)
evaluate(True)

